class Solution {
public:
    vector<int> parent;
    vector<unordered_set<int>> restricted;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        parent.resize(n);
        restricted.resize(n);
        for (int i = 0; i < n; i++) parent[i] = i;

        for (auto& r : restrictions) {
            restricted[r[0]].insert(r[1]);
            restricted[r[1]].insert(r[0]);
        }

        vector<bool> result;
        result.reserve(requests.size());
        for (auto& req : requests) {
            int u = req[0], v = req[1];
            int ru = find(u), rv = find(v);
            if (ru == rv) {
                result.push_back(true);
                continue;
            }
            int small = (restricted[ru].size() <= restricted[rv].size()) ? ru : rv;
            int large = (small == ru) ? rv : ru;
            bool safe = true;
            for (int p : restricted[small]) {
                if (find(p) == large) {
                    safe = false;
                    break;
                }
            }
            if (!safe) {
                result.push_back(false);
                continue;
            }
            parent[small] = large;
            for (int p : restricted[small]) {
                restricted[large].insert(p);
            }
            restricted[small].clear();
            result.push_back(true);
        }
        return result;
    }
};
